ext:mongo.ext:mongo:
db.createCollection('products', {
    validator: {
        $jsonSchema: {
            bsonType: 'object',
            required: ['productId', 'name', 'price'],
            properties: {
                productId: { bsonType: 'string' },
                name: { bsonType: 'string' },
                price: { bsonType: 'double', minimum: 0 },
                inStock: { bsonType: 'bool' }
            }
        }
    },
    validationAction: 'error'
});
print('Created products collection with validation schema');

db.products.createIndex(
    { productId: 1 },
    { unique: true, name: 'idx_product_id' }
);
db.products.createIndex(
    { name: 1, price: -1 },
    { name: 'idx_name_price' }
);
print('Created indexes on products collection');

db.products.insertMany([
    { productId: 'PROD-001', name: 'Widget', price: 29.99, inStock: true },
    { productId: 'PROD-002', name: 'Gadget', price: 49.99, inStock: true },
    { productId: 'PROD-003', name: 'Doohickey', price: 19.99, inStock: false },
    { productId: 'PROD-004', name: 'Thingamajig', price: 39.99, inStock: true }
]);
print('Inserted 4 products');

db.products.updateMany(
    { inStock: false },
    { $set: { status: 'discontinued', updatedAt: new Date() } }
);
print('Updated out-of-stock products');

db.products.aggregate([
    {
        $group: {
            _id: '$inStock',
            count: { $sum: 1 },
            avgPrice: { $avg: '$price' },
            totalValue: { $sum: '$price' }
        }
    },
    {
        $merge: {
            into: 'product_summary',
            whenMatched: 'replace',
            whenNotMatched: 'insert'
        }
    }
]);
print('Created product_summary collection with aggregated data');
